const DRAFT_FORMS=new Set(['composeform','commentform','approvalrequestform','approvalvoteform','rsvpform','groupform','groupnameform','profileform']);
function draftKey(form){return `maomao-draft-v1:${state.user?.id||'guest'}:${state.group?.id||'none'}:${form.id}:${form.dataset.id||form.dataset.kind||''}`}
function saveDraft(form){
 if(!form||!DRAFT_FORMS.has(form.id))return;
 const fields={};
 for(const control of form.elements){if(!control.name||control.type==='file'||control.type==='submit'||control.type==='password')continue;if(control.type==='radio'||control.type==='checkbox'){if(control.checked)fields[control.name]=control.value}else fields[control.name]=control.value}
 try{localStorage.setItem(draftKey(form),JSON.stringify({fields,mood:form.id==='composeform'?mood:null,savedAt:Date.now()}))}catch(e){console.warn('Could not save draft',e)}
}
function restoreDraft(form){
 if(!form||!DRAFT_FORMS.has(form.id))return;
 let draft;try{draft=JSON.parse(localStorage.getItem(draftKey(form))||'null')}catch{return}
 if(!draft?.fields)return;
 for(const control of form.elements){if(!control.name||control.type==='file'||control.type==='submit'||control.type==='password')continue;const value=draft.fields[control.name];if(value===undefined)continue;if(control.type==='radio'||control.type==='checkbox')control.checked=control.value===value;else control.value=value}
 if(form.id==='composeform'&&draft.mood){mood=draft.mood;form.querySelectorAll('[data-mood]').forEach(button=>button.classList.toggle('selected',button.dataset.mood===mood))}
}
function clearDraft(form){if(!form||!DRAFT_FORMS.has(form.id))return;try{localStorage.removeItem(draftKey(form))}catch{}}
document.addEventListener('input',event=>saveDraft(event.target.closest('form')));
document.addEventListener('change',event=>saveDraft(event.target.closest('form')));
