 if(state.page==='calendar'){target=app.querySelector('#calendarbody');html=state.group?(state.view==='day'?dayView():state.view==='week'?weekGrid():monthGrid()):'<div class="empty">你的日常，从一个小圈子开始。<br><button class="primary" data-action="groups">创建 / 加入群组</button></div>'}
