function watchRealtime(){
 if(PREVIEW_MODE||guestMode||!state.user||!state.group){if(realtimeChannel){db.removeChannel(realtimeChannel);realtimeChannel=null;realtimeKey=''}return}
 const key=state.user.id+':'+state.group.id;if(realtimeKey===key)return;
 if(realtimeChannel)db.removeChannel(realtimeChannel);
 realtimeKey=key;
 const changed=()=>{clearTimeout(realtimeTimer);realtimeTimer=setTimeout(()=>{if(!document.hidden)load()},500)};
 let channel=db.channel('maomao:'+key);
 for(const [table,filter] of [['mm_entries',`group_id=eq.${state.group.id}`],['mm_members',`group_id=eq.${state.group.id}`],['mm_approval_requests',`group_id=eq.${state.group.id}`],['mm_responses',null],['mm_approval_votes',null]])channel=channel.on('postgres_changes',{event:'*',schema:'public',table,...(filter?{filter}:{})},changed);
 realtimeChannel=channel.subscribe();
}
async function load(){
 if(!state.user||guestMode||PREVIEW_MODE)return;
 if(loadPromise)return loadPromise;
 const accountId=state.user.id,initial=!hasLoadedAccount;
 if(initial){state.loading=true;render()}
 loadPromise=(async()=>{
  try{
   let profile=await readData(()=>db.from('mm_profiles').select('*').eq('id',accountId).maybeSingle());
   if(!profile)profile=await query(db.from('mm_profiles').insert({id:accountId,name:state.user.user_metadata?.name||state.user.email.split('@')[0]}).select().single());
   const groups=await readData(()=>db.from('mm_groups').select('*').order('created_at'));
   const group=groups.find(g=>g.id===state.group?.id)||groups[0]||null;
   let members=[],entries=[],responses=[];
   if(group){
    const memberships=await readData(()=>db.from('mm_members').select('user_id').eq('group_id',group.id));
    members=memberships.length?await readData(()=>db.from('mm_profiles').select('*').in('id',memberships.map(m=>m.user_id))):[];
    entries=await readData(()=>db.from('mm_entries').select('*').eq('group_id',group.id).order('created_at',{ascending:false}));
    responses=entries.length?await readData(()=>db.from('mm_responses').select('*').in('entry_id',entries.map(e=>e.id))):[];
   }
   const approvals=typeof fetchApprovalState==='function'?await (async()=>{try{return await fetchApprovalState(group?.id)}catch(e){if(!retryableReadError(e))throw e;await new Promise(resolve=>setTimeout(resolve,900));return fetchApprovalState(group?.id)}})():{requests:[],votes:[]};
   if(state.user?.id!==accountId||guestMode)return false;
   if(state.group?.id&&state.group.id!==group?.id)return false;
   const previousGroup=state.lastLoadedGroup,previousIds=state.lastEntryIds;
   const changed=JSON.stringify([state.group?.id,state.profile,state.groups,state.members,state.entries,state.responses,approvalState.requests,approvalState.votes])!==JSON.stringify([group?.id,profile,groups,members,entries,responses,approvals.requests,approvals.votes]);
   state.profile=profile;state.groups=groups;state.group=group;state.members=members;state.entries=entries;state.responses=responses;
   approvalState.requests=approvals.requests;approvalState.votes=approvals.votes;
   state.filter=state.filter.filter(id=>members.some(m=>m.id===id));
   state.lastLoadedGroup=group?.id||null;state.lastEntryIds=new Set(entries.map(e=>e.id));
   const newFriends=previousGroup===group?.id&&previousIds?entries.filter(e=>!previousIds.has(e.id)&&e.user_id!==accountId):[];
   if(newFriends.length)toast(`圈里有 ${newFriends.length} 条新分享，去「有人喊你」看看 🌷`);
   startupError='';if(initial||!hasLoadedAccount){hasLoadedAccount=true;state.loading=false;render();syncTodayWidget()}
   else if(changed)refreshVisibleData();
   watchRealtime();registerExistingPush();
   if(pendingNativeNotification){const payload=pendingNativeNotification;pendingNativeNotification=null;handleNativeNotification(payload)}
   return true;
  }catch(e){console.warn('Could not refresh Maomao',e);if(initial){startupError=retryableReadError(e)?'网络连接失败，请切换 Wi-Fi 或蜂窝网络后重试。':'读取失败：'+e.message;hasLoadedAccount=true;state.loading=false;render()}return false}
 })().finally(()=>{loadPromise=null});
 return loadPromise;
}
function notificationActivity(){
 const me=PREVIEW_MODE?'demo1':state.user?.id;
 const others=state.entries.filter(e=>e.user_id!==me).sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
 const responses=state.responses.filter(r=>r.user_id!==me&&state.entries.some(e=>e.id===r.entry_id))
  .sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
 return {others,responses};
}
function notificationHash(value){let hash=2166136261;for(const char of value){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return (hash>>>0).toString(36)}
function notificationVersions(){
 const {others,responses}=notificationActivity(),versions={};
 for(const e of others)versions['entry:'+e.id]=notificationHash(JSON.stringify([e.updated_at,e.body,e.day,e.kind,e.mood,e.start_time,e.end_time,e.status,e.image?.length,e.image?.slice(0,40),e.image?.slice(-40)]));
 for(const r of responses)versions['response:'+r.id]=notificationHash(JSON.stringify([r.updated_at,r.kind,r.body,r.entry_id]));
 return versions;
}
function notificationStorageKey(){return `maomao-notifications-v1:${PREVIEW_MODE?'demo1':state.user?.id||'guest'}:${state.group?.id||'none'}`}
function notificationCookieKey(){return 'mm_seen_'+notificationHash(notificationStorageKey())}
function seenNotifications(){
 try{const saved=localStorage.getItem(notificationStorageKey());if(saved)return saved}catch{}
 try{const prefix=notificationCookieKey()+'=';const saved=document.cookie.split('; ').find(part=>part.startsWith(prefix));if(saved)return decodeURIComponent(saved.slice(prefix.length))}catch{}
 return state.seenNotificationSnapshot||'';
}
function markNotificationsSeen(){
 const snapshot=notificationHash(JSON.stringify(notificationVersions()));state.seenNotificationSnapshot=snapshot;
 try{localStorage.setItem(notificationStorageKey(),snapshot)}catch{}
 try{document.cookie=`${notificationCookieKey()}=${encodeURIComponent(snapshot)}; Max-Age=31536000; Path=/; SameSite=Lax`}catch{}
 syncTodayWidget();
}
function hasUnreadNotifications(){const versions=notificationVersions();return Object.keys(versions).length>0&&notificationHash(JSON.stringify(versions))!==seenNotifications()}
function render(){if(state.page==='notifications'&&!state.loading)markNotificationsSeen();const hasUnread=hasUnreadNotifications();document.body.dataset.page=state.page;const groupName=state.group?.name||'建立你的第一个圈子';const titles={calendar:['SHARED LITTLE DAYS','小日程','把彼此的日程放在一起，找个合适的时间见面。'],feed:['A LITTLE HELLO','冒个泡',''],events:['BETTER TOGETHER','约一约','把「改天吧」变成一个真正见面的日子。'],approvals:['A LITTLE CHECK','买不买','想买的东西先说说，朋友一起帮你把关。'],'approval-form':['A LITTLE CHECK','发起审批','认真写下想买的理由，再请朋友帮你看看。'],profile:['MY LITTLE WORLD','我的小窝','每一次冒泡，都是生活留下的小小足迹。'],notifications:['SOMEONE IS HERE','有人喊你','朋友的回应和邀请，都在这里。']};const t=titles[state.page];$('#app').innerHTML=`<aside><div class="brand"><span class="logo">••</span>冒冒</div><p class="tagline">在你的世界，冒个泡。</p><button class="groupbtn" data-action="groups">🌱 ${esc(groupName)} <span style="float:right">⌄</span><small>${state.demo?'4 位朋友 · 演示小圈子':state.members.length+' 位朋友 · 我的小圈子'}</small></button><nav>${[['calendar','▦','小日程'],['feed','◌','冒个泡'],['events','♧','约一约'],['approvals','◇','买不买']].map(([p,i,n])=>`<button data-page="${p}" class="${(state.page===p||p==='approvals'&&state.page==='approval-form')?'active':''}"><span>${i}</span>${n}</button>`).join('')}</nav></aside><main><div class="preview-banner">🌷 互动预览 · 所有内容均为模拟数据，刷新后会重置 · 尚未连接账号或云端</div><div class="topbar"><div><button data-page="notifications" data-unread="${hasUnread?'true':'false'}" aria-label="${hasUnread?'有人喊你，有新提醒':'有人喊你'}">♧</button> <button class="topbar-login" data-action="${state.user?'profile':'auth'}" aria-label="${state.user?'我的账号':'登录'}">${state.user?esc(state.profile?.name||'我的账号'):'登录'}</button></div></div><div class="hero ${state.page==='feed'?'feed-hero':''}"><div><div class="eyebrow">${t[0]}</div><h1>${t[1]}<span style="color:var(--orange)">.</span></h1></div>${['calendar','feed','events'].includes(state.page)?`<button class="primary" data-action="compose" data-kind="${state.page==='feed'?'post':state.page==='events'?'event':'plan'}">＋ ${state.page==='calendar'?'记个安排':state.page==='feed'?'说一声':'发起邀约'}</button>`:state.page==='approvals'?'<button class="primary" data-approval-action="new">＋ 发起审批</button>':''}<div class="heroart" aria-hidden="true"><div class="bubble">☺</div><div class="bubble two">☺</div></div></div>${state.loading?'<div class="loading">正在把朋友们的日常带回来…</div>':startupError?startupRecovery():state.page==='calendar'?calendar():state.page==='feed'?feed('post'):state.page==='events'?feed('event'):state.page==='approvals'?approvalsPage():state.page==='approval-form'?approvalForm():state.page==='profile'?profile():notifications()}</main>`;cleanSmallCopy($('#app'));restoreDraft($('#approvalrequestform'));bindSwipe()}
function calendar(){return `<div class="banner"><span>🌿</span><b>${state.demo?'欢迎来到冒冒的示例小圈子':state.members.length?'今天，也在彼此的世界里':'先建一个小圈子，邀请朋友来冒泡'}</b><span>${state.demo?'登录后创建自己的群组，示例内容不会进入你的账号。':'不必填满每一天，有安排时说一声就好。'}</span><span class="spacer"></span><button class="secondary" data-action="groups">${state.demo?'创建小圈子':'圈里人 →'}</button></div><div class="toolbar"><div class="segments">${[['day','这一天'],['week','这一周'],['month','这个月']].map(([v,t])=>`<button data-view="${v}" class="${state.view===v?'active':''}">${t}</button>`).join('')}</div><div class="datecontrols"><button data-step="-1" aria-label="上一${state.view==='day'?'天':state.view==='week'?'周':'月'}">‹</button><strong>${dateTitle()}</strong><button data-step="1" aria-label="下一${state.view==='day'?'天':state.view==='week'?'周':'月'}">›</button><button data-action="today">今天</button><input type="date" aria-label="跳转日期" value="${state.day}" id="jumpdate"></div></div><div class="members"><button class="${!state.filter.length?'selected':''}" data-filter="all">全部朋友</button>${state.members.map(m=>`<button class="${state.filter.includes(m.id)?'selected':''}" data-filter="${m.id}">${esc(m.avatar)} ${esc(m.name)}</button>`).join('')}<span class="hint">↔ 左右滑动切换${state.view==='day'?'日期':state.view==='week'?'周':'月'} · 按时间查看朋友安排</span></div><div id="calendarbody">${!state.group?'<div class="empty">你的日常，从一个小圈子开始。<br><button class="primary" data-action="groups">创建 / 加入群组</button></div>':state.view==='day'?dayView():state.view==='week'?weekGrid():monthGrid()}</div>`}
function dateTitle(){let d=date(state.day);if(state.view==='day')return `${d.getMonth()+1}月${d.getDate()}日 · 周${weekdays[d.getDay()]}`;if(state.view==='month')return `${d.getFullYear()}年 ${d.getMonth()+1}月`;let start=shift(state.day,-((d.getDay()+6)%7)),end=shift(start,6);return `${date(start).getMonth()+1}.${date(start).getDate()} — ${date(end).getMonth()+1}.${date(end).getDate()}`}
function timeLabel(e){return e.start_time?(e.start_time.slice(0,5)+(e.end_time?'–'+e.end_time.slice(0,5):'')):'全天'}
function dayView(){
 const items=visible().flatMap(m=>plans(m.id,state.day).map(e=>({...e,person:m})))
  .sort((a,b)=>(a.start_time||'99:99').localeCompare(b.start_time||'99:99'));
 if(!items.length)return '<div class="empty day-empty">暂时还没有日程</div>';
 return `<section class="timeline"><h3>${esc(state.day)} · 朋友们的日程</h3><div class="timeline-hours">${items.map(e=>`<div class="timeline-row timeline-row-busy"><time>${esc(timeLabel(e))}</time><div class="timeline-item"><span>${esc(e.person.avatar)} ${esc(e.person.name)}</span>${planMarkup(e)}</div></div>`).join('')}</div></section>`;
}
function commentsFor(e){const comments=state.responses.filter(r=>r.entry_id===e.id&&r.kind==='comment').sort((a,b)=>(a.created_at||'').localeCompare(b.created_at||''));return comments.length?`<div class="entry-comments"><div class="comment-thread">${comments.map(c=>`<div class="comment"><b>${esc(member(c.user_id).name)}</b>：${esc(c.body)}</div>`).join('')}</div></div>`:''}
function commentDialog(id){const entry=state.entries.find(e=>e.id===id);if(!entry)return toast('找不到这条分享');modal('给朋友留句话 💬',`<p class="sub">回复 ${esc(member(entry.user_id).name)}：${esc(entry.body.slice(0,140))}</p><form id="commentform" data-id="${esc(id)}"><label>你的评论</label><textarea name="body" maxlength="500" required placeholder="有什么想跟朋友说的？"></textarea><p id="formerror" class="error"></p><div class="modalactions"><button class="primary">发送评论</button></div></form>`)}
function planMarkup(e){return `<div class="plan"><button class="status-reply" data-respond="${esc(e.id)}" data-kind="comment" aria-label="回复${esc(member(e.user_id).name)}的状态">${esc(e.body)}</button><small>${esc(timeLabel(e))}${(e.user_id===state.user?.id||PREVIEW_MODE&&e.user_id==='demo1')?` · <button data-edit="${e.id}">编辑</button>`:''}</small>${commentsFor(e)}</div>`}
function dayCards(){return `<div class="daygrid">${visible().map(m=>{let p=plans(m.id,state.day),post=state.entries.find(e=>e.user_id===m.id&&e.day===state.day&&e.kind==='post');return `<article class="membercard"><div class="cardhead"><span class="avatar">${esc(m.avatar)}</span><div><h3>${esc(m.name)} ${m.id===state.user?.id?'<small style="display:inline">我</small>':''}</h3><small>${moodIcon(post?.mood||p[0]?.mood||'○')} ${post?'今天冒过泡了':p.length?p.length+' 件小安排':'还没有分享今天'}</small></div></div><div class="plans">${p.length?p.map(planMarkup).join(''):'<div class="empty">☁<br>暂无已分享安排</div>'}${m.id===state.user?.id?'<button class="addplan" data-action="compose" data-kind="plan">＋ 再记一件小事</button>':''}</div></article>`}).join('')}</div>`}
function weekGrid(){let start=shift(state.day,-((date(state.day).getDay()+6)%7)),days=Array.from({length:7},(_,i)=>shift(start,i));return `<div class="calendarwrap"><div class="week-scroll" aria-label="一周日程，左右滑动查看日期"><table class="week"><thead><tr><th>圈里人</th>${days.map(d=>`<th><button data-day="${d}">周${weekdays[date(d).getDay()]}<br>${date(d).getMonth()+1}/${date(d).getDate()}</button></th>`).join('')}</tr></thead><tbody>${visible().map(m=>`<tr><td><span class="avatar">${esc(m.avatar)}</span><p>${esc(m.name)}</p></td>${days.map(d=>`<td>${plans(m.id,d).map(planMarkup).join('')||'<span style="color:#ccc">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function monthGrid(){let first=date(state.day);first.setDate(1);let start=shift(key(first),-((first.getDay()+6)%7));return `<div class="month">${['一','二','三','四','五','六','日'].map(w=>`<div class="weekday">周${w}</div>`).join('')}${Array.from({length:42},(_,i)=>{let d=shift(start,i),ms=visible().filter(m=>plans(m.id,d).length),count=ms.reduce((n,m)=>n+plans(m.id,d).length,0);return `<button class="monthday ${d===today()?'today':''} ${date(d).getMonth()!==first.getMonth()?'out':''}" data-day="${d}"><b>${date(d).getDate()}</b>${count?`<div class="month-markers"><span class="month-avatars">${ms.slice(0,4).map(m=>`<span class="avatar month-avatar" title="${esc(m.name)}" aria-label="${esc(m.name)}">${esc(m.avatar)}</span>`).join('')}</span><span class="month-summary">${ms.length}人 · ${count}项安排</span></div>`:''}</button>`}).join('')}</div>`}
function rsvpReason(r){if(!r)return '';const body=r.body||'';return ['可以参加','不能参加','待定','accept','decline','maybe','join','我也去'].includes(body)?'':body}
function invitePoll(e,responses,mine){const options=[['accept','可以参加'],['decline','不能参加']],counts={accept:responses.filter(x=>['accept','join'].includes(x.kind)).length,decline:responses.filter(x=>x.kind==='decline').length},total=counts.accept+counts.decline;return `<div class="invite-poll" role="group" aria-label="${esc(e.body.split('\n')[0])}的投票">${options.map(([vote,label])=>`<button class="invite-poll-choice ${mine?.kind===vote||vote==='accept'&&mine?.kind==='join'?'selected':''}" data-invite-card="${esc(e.id)}" data-poll-vote="${vote}" aria-label="${label}，${counts[vote]}票"><span class="invite-poll-fill" style="width:${total?Math.round(counts[vote]/total*100):0}%"></span><span class="invite-poll-label">${label}</span><b>${counts[vote]}</b></button>`).join('')}</div>`}
function dailyMoods(day){
  const latest=new Map();
  state.entries.filter(e=>e.day===day&&e.mood&&e.mood!=='○').sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')).forEach(e=>{if(!latest.has(e.user_id))latest.set(e.user_id,e)});
  return [...latest.values()];
}
function moodCalendar(){
  const selected=state.moodDay,month=state.moodMonth,first=date(month+'-01'),offset=(first.getDay()+6)%7;
  const days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();
  const cells=Array.from({length:offset+days},(_,i)=>{
    const n=i-offset+1;if(n<1)return '<span class="mood-calendar-blank"></span>';
    const day=month+'-'+String(n).padStart(2,'0'),entries=dailyMoods(day);
    return `<button class="mood-calendar-day ${day===selected?'selected':''} ${day===today()?'today':''}" data-mood-day="${day}" aria-label="${n}日，${entries.length}位朋友记录心情"><span>${n}</span>${entries.length?`<span class="mood-calendar-mark">${entries.slice(0,4).map(e=>moodIcon(e.mood)).join('')}${entries.length>4?`<b>+${entries.length-4}</b>`:''}</span>`:''}</button>`;
  }).join('');
  const chosen=dailyMoods(selected);
  return `<section class="mood-calendar"><button class="mood-calendar-toggle" data-action="mood-calendar" aria-expanded="${state.moodCalendarOpen}"><img src="assets/crayon/nav-calendar.png" alt=""><span>心情日历</span><span class="mood-calendar-chevron">${state.moodCalendarOpen?'收起 ↑':'展开 ↓'}</span></button>${state.moodCalendarOpen?`<div class="mood-calendar-panel"><div class="mood-calendar-heading"><button data-mood-step="-1" aria-label="上个月">‹</button><strong>${first.getFullYear()}年${first.getMonth()+1}月</strong><button data-mood-step="1" aria-label="下个月">›</button></div><div class="mood-calendar-grid">${['一','二','三','四','五','六','日'].map(w=>`<span class="mood-calendar-weekday">${w}</span>`).join('')}${cells}</div><div class="mood-calendar-daily"><b>${selected===today()?'今天':`${date(selected).getMonth()+1}月${date(selected).getDate()}日`}的心情</b>${chosen.length?chosen.map(e=>`<div>${moodIcon(e.mood)}<span>${esc(member(e.user_id).name)}</span><span>${moodName(moodKey(e.mood))}</span></div>`).join(''):'<p>这一天还没有朋友记录心情。</p>'}</div></div>`:''}</section>`;
}
function postFeed(){
  const entries=state.entries.filter(e=>e.kind==='post').sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
  let previousPaper=null;
  for(const entry of [...entries].reverse()){
    if(!bubblePaperAssignments.has(entry.id))bubblePaperAssignments.set(entry.id,bubblePaperPalette[previousPaper===null?0:(bubblePaperPalette.indexOf(previousPaper)+1)%bubblePaperPalette.length]);
    previousPaper=bubblePaperAssignments.get(entry.id);
  }
  return `<div class="feed scrapbook-feed">${moodCalendar()}${entries.length?entries.map(e=>{
    const m=member(e.user_id),responses=state.responses.filter(x=>x.entry_id===e.id);
    const hasPhoto=e.image?.startsWith('data:image/');
    const comments=responses.filter(x=>x.kind==='comment');
    const paper=bubblePaperAssignments.get(e.id);
    const compact=!hasPhoto&&e.body.trim().length<=20&&comments.length===0;
    return `<article class="post bubble-sticker bubble-${paper}${compact?' bubble-compact':''}"><div class="bubble-sticker-content">
      <div class="postheader"><span class="avatar">${esc(m.avatar)}</span><div><b>${esc(m.name)}</b><small>${esc(e.day)}</small></div></div>
      <button class="status-reply" data-respond="${esc(e.id)}" data-kind="comment" aria-label="回复${esc(m.name)}的状态">${esc(e.body)}</button>
      ${hasPhoto?`<img class="bubble-photo" src="${esc(e.image)}" alt="朋友分享的照片">`:''}
      <div class="bubble-sticker-bottom"><div class="bubble-sticker-replies">
        <div class="postactions"><button data-respond="${esc(e.id)}" data-kind="like"><img class="bubble-like" src="assets/crayon/${responses.some(x=>x.kind==='like'&&x.user_id===(PREVIEW_MODE?'demo1':state.user?.id))?'like-filled':'like-outline'}.png" alt=""> 接住你的冒泡 · ${responses.filter(x=>x.kind==='like').length}</button>${e.user_id===state.user?.id||PREVIEW_MODE&&e.user_id==='demo1'?`<button data-edit="${esc(e.id)}">编辑</button>`:''}</div>
        ${comments.map(c=>`<div class="comment"><b>${esc(member(c.user_id).name)}</b>：${esc(c.body)}</div>`).join('')}
      </div><span class="bubble-sticker-mood">${moodIcon(e.mood)}</span></div>
    </div></article>`;
  }).join(''):'<div class="empty">这里还很安静，来冒第一个泡吧。</div>'}</div>`;
}
function feed(kind){if(kind==='post')return postFeed();let entries=state.entries.filter(e=>e.kind===kind).sort((a,b)=>kind==='event'?a.day.localeCompare(b.day):(b.created_at||'').localeCompare(a.created_at||''));return `<div class="feed ${kind==='post'?'scrapbook-feed':''}">${entries.length?entries.map(e=>{let m=member(e.user_id),r=state.responses.filter(x=>x.entry_id===e.id),mine=r.find(x=>x.user_id===(PREVIEW_MODE?'demo1':state.user?.id)&&['accept','decline','maybe','join'].includes(x.kind));return `<article class="post ${kind==='event'?'invite-card':''}" ${kind==='event'?`data-invite-card="${esc(e.id)}" tabindex="0" aria-label="查看${esc(m.name)}的邀约并回复"`:''}><div class="postheader"><span class="avatar">${esc(m.avatar)}</span><div><b>${esc(m.name)} ${moodIcon(e.mood)}</b><small>${esc(e.day)}${kind==='event'?' · 群组邀约':''}</small></div></div>${kind==='event'?`<h3 class="invite-question">${esc(e.body.split('\n')[0])}</h3>${invitePoll(e,r,mine)}`:`<button class="status-reply" data-respond="${esc(e.id)}" data-kind="comment" aria-label="回复${esc(m.name)}的状态">${esc(e.body)}</button>`}${e.image?.startsWith('data:image/')?`<img src="${esc(e.image)}" alt="朋友分享的照片">`:''}<div class="postactions">${kind==='event'?'':`<button data-respond="${esc(e.id)}" data-kind="like">♡ 接住你的冒泡 · ${r.filter(x=>x.kind==='like').length}</button>`}${e.user_id===state.user?.id||PREVIEW_MODE&&e.user_id==='demo1'?`<button data-edit="${esc(e.id)}">编辑</button>`:''}</div>${kind==='event'?r.filter(x=>['accept','decline','maybe','join'].includes(x.kind)&&rsvpReason(x)).map(x=>`<div class="comment"><b>${esc(member(x.user_id).name)}</b>：${esc(rsvpReason(x))}</div>`).join(''):r.filter(x=>x.kind==='comment').map(c=>`<div class="comment"><b>${esc(member(c.user_id).name)}</b>：${esc(c.body)}</div>`).join('')}</article>`}).join(''):`<div class="empty">${kind==='event'?'还没有邀约，发起下一次见面吧。':'这里还很安静，来冒第一个泡吧。'}</div>`}</div>`}
function inviteDialog(id,prefill){const e=state.entries.find(x=>x.id===id&&x.kind==='event');if(!e)return toast('找不到这条邀约');const mine=state.responses.find(x=>x.entry_id===id&&x.user_id===(PREVIEW_MODE?'demo1':state.user?.id)&&['accept','decline','maybe','join'].includes(x.kind));const selected=prefill||(mine?.kind==='join'?'accept':mine?.kind);modal('回复这次邀约',`<p class="sub">${esc(member(e.user_id).name)}邀请你：${esc(e.body)}</p><form id="rsvpform" data-id="${esc(id)}"><div class="rsvp-options">${[['accept','可以参加'],['decline','不能参加']].map(([value,label])=>`<label><input type="radio" name="vote" value="${value}" ${selected===value?'checked':''} required><span>${label}</span></label>`).join('')}</div><label for="rsvp-reason">补充理由（可选）</label><textarea id="rsvp-reason" name="reason" maxlength="500" placeholder="想说点什么的话，可以写在这里">${esc(rsvpReason(mine))}</textarea><p id="formerror" class="error"></p><div class="modalactions"><button class="primary" type="submit">保存回复</button></div></form>`);$('#modal').classList.add('invite-dialog')}

function profile(){if(!state.user)return `<div class="profile"><span class="avatar">🐱</span><h2 style="margin-top:20px">来啦，等你冒个泡</h2><p class="sub">登录后，心情、安排和小圈子都跟着账号走。<br>换个设备，也能接着分享。</p><button class="primary" data-action="auth">登录 / 注册</button> <button class="secondary" data-action="guest">以游客身份使用</button><p class="guest-local-note">游客内容只保存在这台设备或这个浏览器。</p></div>`;let mine=state.entries.filter(e=>e.user_id===state.user.id);return `<div class="profile"><span class="avatar">${esc(state.profile?.avatar)}</span><h2 style="margin-top:15px">${esc(state.profile?.name)}</h2><p class="sub">${esc(state.user.email)}</p><div class="stats"><div><b>${state.groups.length}</b><small>小圈子</small></div><div><b>${mine.filter(e=>e.kind==='plan').length}</b><small>当前圈子安排</small></div><div><b>${mine.filter(e=>e.kind==='post').length}</b><small>当前圈子冒泡</small></div></div><button class="secondary" data-action="editprofile">编辑资料</button> <button class="secondary" data-action="logout">${guestMode?'退出游客模式':'退出登录'}</button>${guestMode?'<button class="secondary" data-action="auth">登录账号</button>':''}<p class="${guestMode?'guest-local-note':'footnote'}">${guestMode?'游客内容仅保存在这台设备，不会同步到账号。':'内容保存到云端账号，仅当前群组成员可以查看你的分享。'}<br>这里的统计对应当前圈子。切换圈子可查看其他记录。</p></div>`}
function notifications(){
 const {others,responses}=notificationActivity();
 return `<div class="feed">${!PREVIEW_MODE&&native()?'<button class="primary" data-action="enable-notifications">开启手机横幅通知</button>':''}<h3>✨ 圈里最近更新</h3>${others.slice(0,20).map(e=>`<div class="notification"><b>${esc(member(e.user_id).avatar)} ${esc(member(e.user_id).name)}</b> ${e.kind==='plan'?'更新了日程':e.kind==='event'?'发起了邀约':'分享了心情'} · ${esc(e.day)}<p>${esc(e.body)}</p>${commentsFor(e)}</div>`).join('')||'<div class="empty">朋友们还没有分享新的内容。</div>'}<h3>💌 圈里的互动</h3>${responses.slice(0,20).map(r=>{const parent=state.entries.find(e=>e.id===r.entry_id);const target=parent?`${esc(member(parent.user_id).name)}的${parent.kind==='plan'?'日程':parent.kind==='event'?'邀约':'冒泡'}`:'一条分享';const action=r.kind==='comment'?`评论了${target}：${esc(r.body)}`:r.kind==='decline'?`暂时不能参加${target}`:r.kind==='maybe'?`还在考虑${target}`:r.kind==='accept'||r.kind==='join'?`接受了${target}`:r.kind==='like'?`喜欢了${target}`:`回应了${target}`;return `<div class="notification"><b>${esc(member(r.user_id).name)}</b> ${action}</div>`}).join('')||'<div class="empty">还没有新的互动。</div>'}</div>`
}
function authDialog(){if(PREVIEW_MODE){toast('这是不连接数据库的公开预览，暂不支持真实注册。');return}modal('来啦，冒个泡 🐱',`<p class="sub">${authMode==='signup'?'认识一下，把日常连起来。':'登录后，回到你熟悉的小圈子。'}</p><form id="authform">${authMode==='signup'?'<label>朋友怎么称呼你</label><input name="name" maxlength="30" required placeholder="你的昵称">':''}<label>邮箱</label><input name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label>密码</label><input name="password" type="password" minlength="8" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required placeholder="至少 8 位"><p id="formerror" class="error"></p><div class="modalactions"><button class="primary" type="submit">${authMode==='signup'?'注册账号':'登录'}</button><button type="button" class="secondary" data-action="authswitch">${authMode==='signup'?'已有账号':'创建账号'}</button><button type="button" class="secondary" data-action="guest">以游客身份使用</button></div></form><p class="footnote">注册需验证邮箱。内容随账号保存，不会导入演示内容。</p>`)}
function compose(kind,id){if(!requireUser())return;if(!state.group){groupsDialog();return}const e=state.entries.find(e=>e.id===id);mood=e?.mood||'happy';modal(e?'编辑这次分享':kind==='plan'?'记个小安排':kind==='post'?'今天，冒个泡':'发起下一次见面',`<form id="composeform" data-kind="${kind}" data-id="${id||''}"><label>哪一天</label><input name="day" type="date" value="${e?.day||state.day}" required>${kind==='plan'||kind==='event'?`<div class="time-pair"><div><label>开始时间（可选）</label><input name="start_time" type="time" value="${e?.start_time?.slice(0,5)||''}"></div><div><label>结束时间（可选）</label><input name="end_time" type="time" value="${e?.end_time?.slice(0,5)||''}"></div></div>`:''}<label>${kind==='plan'?'准备做什么？':kind==='event'?'想和朋友一起做什么？':'想分享些什么？'}</label><textarea name="body" maxlength="4000" required placeholder="一点小计划，一句碎碎念…">${esc(e?.body||'')}</textarea><label>这一天的心情</label><div class="moods">${MOODS.map(m=>`<button type="button" data-mood="${m}" aria-label="${moodName(m)}" class="${m===moodKey(mood)?'selected':''}">${moodIcon(m)}<span>${moodName(m)}</span></button>`).join('')}</div>${kind==='post'?'<label>照片（可选，最大 8MB）</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp">':''}<p class="footnote">分享到「${esc(state.group.name)}」，圈内所有朋友可见。</p><p id="formerror" class="error"></p><div class="modalactions"><button class="primary" type="submit">${e?'保存修改':'分享给朋友'}</button></div></form>`)}
function groupsDialog(){if(guestMode){modal('我的本地小圈子 🌱',`<div class="groupentry"><div><b>${esc(state.group.name)}</b><small>仅保存在这台设备</small></div><button class="secondary" data-rename-group="${esc(state.group.id)}">改名</button></div><p>登录账号后可以创建或加入共享圈子；游客内容不会自动上传。</p>`);return}if(PREVIEW_MODE){toast('预览中展示模拟小圈子；正式版可以创建、加入多个群组。');return}if(!requireUser())return;modal('我的小圈子 🌱',`${state.groups.map(g=>`<div class="groupentry"><div><b>${esc(g.name)}</b><small>邀请码：${esc(g.code)}</small></div><div class="groupentry-actions">${g.owner===state.user.id?`<button type="button" class="secondary" data-rename-group="${esc(g.id)}">改名</button>`:''}<button type="button" class="secondary" data-group="${esc(g.id)}">进入</button></div></div>`).join('')||'<p class="sub">还没有小圈子，创建一个或加入朋友的圈子。</p>'}<form id="groupform"><label>创建小圈子</label><input name="name" maxlength="40" placeholder="例如：周末不宅家"><div class="modalactions"><button class="primary" name="create" type="submit" value="create">创建群组</button></div><label>或者，填写朋友的邀请码</label><input name="code" placeholder="粘贴邀请码" maxlength="40"><div class="modalactions"><button class="secondary" name="join" type="submit" value="join">加入群组</button></div><p id="formerror" class="error"></p></form><p class="footnote">分享邀请码即可邀请朋友；仅获得邀请码的登录用户可以加入。</p>`)}
function renameGroupDialog(id){if(!requireUser())return;const group=state.groups.find(g=>g.id===id);if(!group||group.owner!==state.user.id){toast('只有圈子创建者可以改名');return}modal('修改圈子名',`<form id="groupnameform" data-id="${esc(group.id)}"><label for="group-new-name">新的圈子名</label><input id="group-new-name" name="name" maxlength="40" required value="${esc(group.name)}"><p id="formerror" class="error"></p><div class="modalactions"><button class="primary" type="submit">保存名称</button></div></form>`)}
function navigate(n){if(state.view==='month'){let d=date(state.day),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);const end=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,end));state.day=key(d)}else state.day=shift(state.day,n*(state.view==='week'?7:1));render()}
function bindSwipe(){let el=$('#calendarbody');if(!el)return;let start;el.addEventListener('touchstart',e=>{start=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});el.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start[0],dy=e.changedTouches[0].clientY-start[1];if(e.target.closest('.week-scroll'))return;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)navigate(dx<0?1:-1);start=null},{passive:true})}
document.addEventListener('click',async ev=>{const invite=ev.target.closest('[data-invite-card]');const b=ev.target.closest('button');if(b?.dataset.pollVote){inviteDialog(b.dataset.inviteCard,b.dataset.pollVote);return}if(invite&&!b){inviteDialog(invite.dataset.inviteCard);return}if(!b)return;if(b.dataset.action==='mood-calendar'){state.moodCalendarOpen=!state.moodCalendarOpen;render();return}if(b.dataset.moodStep){const month=date(state.moodMonth+'-01');month.setMonth(month.getMonth()+Number(b.dataset.moodStep));state.moodMonth=key(month).slice(0,7);state.moodDay=state.moodMonth+'-01';render();return}if(b.dataset.moodDay){state.moodDay=b.dataset.moodDay;render();return}try{if(b.dataset.page){state.page=b.dataset.page;render()}if(b.dataset.view){state.view=b.dataset.view;render()}if(b.dataset.step)navigate(Number(b.dataset.step));if(b.dataset.day){state.day=b.dataset.day;state.view='day';render()}if(b.dataset.filter){let id=b.dataset.filter;if(id==='all')state.filter=[];else state.filter=state.filter.includes(id)?state.filter.filter(x=>x!==id):[...state.filter,id];render()}if(b.dataset.mood){mood=b.dataset.mood;document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('selected',x.dataset.mood===mood));saveDraft(b.closest('form'))}if(b.dataset.edit){let e=state.entries.find(x=>x.id===b.dataset.edit);compose(e.kind,e.id)}if(b.dataset.renameGroup){renameGroupDialog(b.dataset.renameGroup);return}if(b.dataset.group){state.group=state.groups.find(g=>g.id===b.dataset.group);$('#modal').close();if(guestMode){guestSave();render()}else{if(loadPromise)await loadPromise;await load()}}if(b.dataset.rsvp){if(PREVIEW_MODE||guestMode){previewVote(b.dataset.rsvp,b.dataset.vote);return}if(!requireUser())return;await query(db.rpc('mm_set_rsvp',{p_entry:b.dataset.rsvp,p_vote:b.dataset.vote}));await load();toast('已保存你的邀约回复');return}if(b.dataset.respond){if(PREVIEW_MODE||guestMode){if(b.dataset.kind==='comment'){commentDialog(b.dataset.respond);return}if(b.dataset.kind==='join'){previewVote(b.dataset.respond,'accept');return}const id=b.dataset.respond,kind=b.dataset.kind;if(!state.responses.some(r=>r.entry_id===id&&r.user_id===(guestMode?GUEST_ID:'demo1')&&r.kind===kind)){state.responses.push({id:crypto.randomUUID(),entry_id:id,user_id:guestMode?GUEST_ID:'demo1',kind,body:'接住了',created_at:new Date().toISOString()});guestSave();render()}return}if(!requireUser())return;let kind=b.dataset.kind,id=b.dataset.respond;if(kind==='join'){await query(db.rpc('mm_set_rsvp',{p_entry:id,p_vote:'accept'}));await load();toast('已接受邀约');return}if(kind==='comment')commentDialog(id);else{if(state.responses.some(r=>r.entry_id===id&&r.user_id===state.user.id&&r.kind===kind)){toast('你已经回应过啦');return}await query(db.from('mm_responses').insert({entry_id:id,user_id:state.user.id,kind,body:kind==='join'?'我也去':'接住了'}));await load();toast(kind==='join'?'报名成功，期待见面！':'朋友收到你的回应啦')}}switch(b.dataset.action){case'close':$('#modal').close();break;case'auth':authDialog();break;case'retry-startup':startupError='';if(state.user){hasLoadedAccount=false;await load()}else{const result=await sessionWithTimeout();if(result.error)throw result.error;if(result.data.session){state.user=result.data.session.user;hasLoadedAccount=false;await load()}else authDialog()}break;case'guest':if($('#modal').open)$('#modal').close();guestStart();break;case'authswitch':authMode=authMode==='login'?'signup':'login';authDialog();break;case'groups':groupsDialog();break;case'compose':compose(b.dataset.kind);break;case'today':state.day=today();render();break;case'profile':state.page='profile';render();break;case'enable-notifications':await enableMobileNotifications();break;case'logout':if(guestMode){guestLeave();break}if(PREVIEW_MODE){toast('预览模式无需退出账号');break}if(pushToken)await query(db.from('mm_device_tokens').delete().eq('user_id',state.user.id).eq('token',pushToken)).catch(()=>{});await db.auth.signOut();state.user=null;state.profile=null;state.groups=[];state.demo=false;state.filter=[];state.group=null;state.members=[];state.entries=[];state.responses=[];approvalState.requests=[];approvalState.votes=[];render();syncTodayWidget();break;case'editprofile':if(guestMode){modal('我的样子',`<form id="profileform"><label>昵称</label><input name="name" maxlength="30" required value="${esc(state.profile.name)}"><label>头像</label><select name="avatar">${['🐱','🐻','🐰','🐳','🐼','🦊','🌻','🌈'].map(a=>`<option ${a===state.profile.avatar?'selected':''}>${a}</option>`).join('')}</select><p id="formerror" class="error"></p><div class="modalactions"><button class="primary">保存资料</button></div></form>`);break}if(PREVIEW_MODE){toast('预览中无法更改真实账号资料');break}modal('我的样子',`<form id="profileform"><label>昵称</label><input name="name" maxlength="30" required value="${esc(state.profile.name)}"><label>头像</label><select name="avatar">${['🐱','🐻','🐰','🐳','🐼','🦊','🌻','🌈'].map(a=>`<option ${a===state.profile.avatar?'selected':''}>${a}</option>`).join('')}</select><p id="formerror" class="error"></p><div class="modalactions"><button class="primary">保存资料</button></div></form>`);break}}catch(e){error(e.message)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-invite-card]')){e.preventDefault();inviteDialog(e.target.dataset.inviteCard)}});
document.addEventListener('change',e=>{if(e.target.id==='jumpdate'&&e.target.value){state.day=e.target.value;render()}});
async function compress(file){if(file.size>8*1024*1024)throw Error('照片请小于 8MB');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 照片');let bitmap=await createImageBitmap(file),c=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));c.width=bitmap.width*scale;c.height=bitmap.height*scale;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();let data=c.toDataURL('image/jpeg',.72);if(data.length>=1500000)throw Error('照片压缩后仍过大，请换一张');return data}
document.addEventListener('submit',async ev=>{const f=ev.target;if(!['authform','composeform','groupform','groupnameform','commentform','profileform','rsvpform'].includes(f.id))return;ev.preventDefault();if(f.dataset.submitting==='true')return;f.dataset.submitting='true';const fd=new FormData(f),button=ev.submitter;if(button)button.disabled=true;try{if(f.id==='authform'){const email=fd.get('email').trim(),password=fd.get('password');if(authMode==='signup'){const r=await db.auth.signUp({email,password,options:{data:{name:fd.get('name').trim()},emailRedirectTo:window.MAOMAO_CONFIG?.authRedirectUrl||(location.protocol.startsWith('http')?location.origin+location.pathname:undefined)}});if(r.error)throw r.error;if(!r.data.session){error('验证邮件已发送，请完成邮箱验证后登录。');return}}else{const r=await db.auth.signInWithPassword({email,password});if(r.error)throw r.error}const {data}=await db.auth.getSession();state.user=data.session?.user;guestMode=false;state.demo=false;state.group=null;$('#modal').close();startupError='';hasLoadedAccount=false;if(await load())toast('来啦，欢迎回到冒冒')}if(f.id==='groupform'){if(guestMode){if(button.value!=='create')throw Error('游客圈子只保存在这台设备，无法加入云端圈子');let name=String(fd.get('name')||'').trim();if(!name)throw Error('给圈子起个名字吧');let g={id:crypto.randomUUID(),name,owner:GUEST_ID,code:'LOCAL'};state.groups.push(g);state.group=g;guestSave();$('#modal').close();render();return}let g;if(button.value==='create'){let name=fd.get('name').trim();if(!name)throw Error('给圈子起个名字吧');g=await query(db.rpc('mm_create_group',{n:name}))}else{let code=fd.get('code').trim();if(!code)throw Error('请填写邀请码');g=await query(db.rpc('mm_join_group',{c:code}))}state.group={id:g};clearDraft(f);$('#modal').close();if(loadPromise)await loadPromise;await load();toast('小圈子已准备好')}if(f.id==='groupnameform'){const group=state.groups.find(g=>g.id===f.dataset.id);if(!group||group.owner!==state.user.id)throw Error('只有圈子创建者可以改名');const name=String(fd.get('name')||'').trim();if(!name||[...name].length>40)throw Error('圈子名请填写 1 至 40 个字');if(guestMode){group.name=name;guestSave();$('#modal').close();render();return}const updated=await query(db.from('mm_groups').update({name}).eq('id',group.id).eq('owner',state.user.id).select('id'));if(updated.length!==1)throw Error('未能保存圈子名，请重试');clearDraft(f);$('#modal').close();await load();toast('圈子名已更新')}if(f.id==='composeform'){let body=fd.get('body').trim();if(!body)throw Error('写一点内容再分享吧');let values={group_id:state.group.id,user_id:PREVIEW_MODE?'demo1':state.user.id,day:fd.get('day'),kind:f.dataset.kind,body,mood,status:f.dataset.kind==='plan'?'有安排':'报名中',start_time:fd.get('start_time')||null,end_time:fd.get('end_time')||null};if(values.start_time&&values.end_time&&values.end_time<=values.start_time)throw Error('结束时间需要晚于开始时间');const file=fd.get('image');if(file?.size)values.image=await compress(file);if(PREVIEW_MODE||guestMode){if(f.dataset.id){const e=state.entries.find(x=>x.id===f.dataset.id);if(e)Object.assign(e,values)}else state.entries.unshift({...values,id:crypto.randomUUID(),created_at:new Date().toISOString(),user_id:guestMode?GUEST_ID:'demo1'});}else if(f.dataset.id){const updated=await query(db.from('mm_entries').update(values).eq('id',f.dataset.id).eq('user_id',state.user.id).select('id'));if(updated.length!==1)throw Error('修改未保存，请重试')}else await query(db.from('mm_entries').insert(values).select('id'));state.day=values.day;clearDraft(f);$('#modal').close();if(PREVIEW_MODE||guestMode){guestSave();render()}else await load();toast('已经分享到小圈子啦')}if(f.id==='commentform'){let body=fd.get('body').trim();if(!body)throw Error('写一句话吧');if(PREVIEW_MODE||guestMode){state.responses.push({id:crypto.randomUUID(),entry_id:f.dataset.id,user_id:guestMode?GUEST_ID:'demo1',kind:'comment',body,created_at:new Date().toISOString()});clearDraft(f);$('#modal').close();guestSave();render();toast('评论已添加 🌷')}else{await query(db.from('mm_responses').insert({entry_id:f.dataset.id,user_id:state.user.id,kind:'comment',body}).select('id'));clearDraft(f);$('#modal').close();await load();toast('评论已发送 🌷')}}if(f.id==='rsvpform'){const vote=fd.get('vote'),reason=String(fd.get('reason')||'').trim();if(!['accept','decline'].includes(vote))throw Error('请选择一个回复');if(PREVIEW_MODE||guestMode){previewVote(f.dataset.id,vote,reason);clearDraft(f)}else{if(!requireUser())return;await query(db.rpc('mm_set_rsvp',{p_entry:f.dataset.id,p_vote:vote,p_reason:reason}));clearDraft(f);await load();toast('已保存你的邀约回复')}$('#modal').close()}if(f.id==='profileform'){if(guestMode){state.profile.name=String(fd.get('name')||'').trim();state.profile.avatar=fd.get('avatar');state.members[0]=state.profile;guestSave();$('#modal').close();render();return}const updated=await query(db.from('mm_profiles').update({name:fd.get('name').trim(),avatar:fd.get('avatar')}).eq('id',state.user.id).select('id'));if(updated.length!==1)throw Error('资料未保存，请重试');clearDraft(f);$('#modal').close();await load();toast('资料已保存')}}catch(e){error(e.message)}finally{delete f.dataset.submitting;if(button?.isConnected)button.disabled=false}});
function previewVote(id,vote,reason=''){state.responses=state.responses.filter(r=>!(r.entry_id===id&&r.user_id===(guestMode?GUEST_ID:'demo1')&&['join','accept','decline','maybe'].includes(r.kind)));state.responses.push({id:crypto.randomUUID(),entry_id:id,user_id:guestMode?GUEST_ID:'demo1',kind:vote,body:reason||({accept:'可以参加',decline:'不能参加',maybe:'待定'}[vote]||vote),created_at:new Date().toISOString()});guestSave();render();toast('已记录回复：'+({accept:'可以参加',decline:'不能参加',maybe:'待定'}[vote]||vote))}
if(PREVIEW_MODE)demoData();render();if(!PREVIEW_MODE){let bootFinished=false;const bootTimer=setTimeout(()=>{if(!bootFinished&&!guestMode){startupError='登录状态恢复超时，请检查网络后重试。';render()}},12000);sessionWithTimeout().then(async({data,error})=>{bootFinished=true;clearTimeout(bootTimer);if(guestMode)return;if(error)throw error;if(data.session){guestMode=false;state.user=data.session.user;state.demo=false;state.group=null;startupError='';await load()}else if(guestRead())guestStart();else{startupError='';render()}}).catch(e=>{bootFinished=true;clearTimeout(bootTimer);startupError='登录状态暂时无法恢复：'+(e?.message||'请检查网络');render()})}if(native()){native().addListener('pushToken',({token,environment})=>savePushToken(token,environment));native().addListener('notificationTapped',handleNativeNotification);native().consumeNotification().then(({notification})=>handleNativeNotification(notification)).catch(()=>{})}if(!PREVIEW_MODE)db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){hasLoadedAccount=false;if(realtimeChannel){db.removeChannel(realtimeChannel);realtimeChannel=null;realtimeKey=''}state.user=null;state.profile=null;state.groups=[];state.group=null;state.members=[];state.entries=[];state.responses=[];approvalState.requests=[];approvalState.votes=[];state.demo=false;render();if(guestRead())guestStart()}if(event==='TOKEN_REFRESHED'&&session)state.user=session.user});function resumeSync(){if(!state.user||guestMode||PREVIEW_MODE||document.hidden)return;const now=Date.now();if(now-lastFocusSync<30000)return;lastFocusSync=now;load()}window.addEventListener('focus',()=>{if(native())native().consumeNotification().then(({notification})=>handleNativeNotification(notification)).catch(()=>{});resumeSync()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)resumeSync()});if(!PREVIEW_MODE)setInterval(()=>{if(state.user&&!guestMode&&!document.hidden)load()},30000);

